SELECT DISTINCT io.id AS inspectionOrderId, sip.code AS planCode, io.batch_no AS batchNo, io.order_no AS orderNo, sip.material_name AS materialName, sip.material_code AS materialCode, sip.material_spec AS materialSpec, io.create_time AS requestTime, io.order_status AS orderStatus, io.sample_audit_process_instance_id AS processInstanceId FROM lm_inspection_order io INNER JOIN lm_stability_plan_timepoint_task tpTask ON tpTask.inspection_order_id = io.id AND tpTask.is_deleted = 0 INNER JOIN lm_stability_inspect_plan sip ON tpTask.plan_id = sip.id AND sip.is_deleted = 0 WHERE io.is_deleted = 0 AND io.order_status = 'SAMPLE_AUDIT_PENDING' AND io.sample_audit_process_instance_id IS NOT NULL
AND sip.code LIKE CONCAT('%', #{query.planCode}, '%')
AND io.order_no LIKE CONCAT('%', #{query.orderNo}, '%')
AND io.batch_no LIKE CONCAT('%', #{query.batchNo}, '%')
AND sip.material_id = #{query.materialId}
AND sip.material_id IN
#{id}
AND io.create_time >= #{query.requestTimeStart}
AND io.create_time <= #{query.requestTimeEnd}
ORDER BY io.create_time DESC, io.order_no ASC
